/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Functions: CatalogAlbumTracks
 * Internal
 *   Functions: details, expectedDuration
 *   Constants: layout, stateLabels
 * @end-catalog */

import { useEffect, useRef, type CSSProperties } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Link } from 'react-router';
import { useLocalization } from '../../localization/LocalizationProvider';
import { useAdminAccess, useAdminText } from './AdminAccess';
import { adminEndpointRequest } from './adminTransport';
import { catalogAlbumTracksSchema, expectedSummary, expectedSummaryVariables, type CatalogAlbumExpectedRow,
  type CatalogAlbumExpectedSummary, type CatalogAlbumTrack } from './catalogAlbumTracksApi';
import styles from './adminStyles';

// Inline layout keeps this lazily loaded section out of the shared administrator stylesheet and class map.
const layout = {
  list: { listStyle: 'none', margin: '.75rem 0 0', padding: 0 },
  row: { display: 'grid', gridTemplateColumns: '2.25rem minmax(0, 1fr)', gap: '.75rem', alignItems: 'baseline', borderTop: '1px solid var(--color-border)', padding: '.7rem 0' },
  position: { color: 'var(--color-text-muted)', fontVariantNumeric: 'tabular-nums', textAlign: 'end' },
  title: { display: 'inline-block', fontWeight: 650, minHeight: '1.5rem', overflowWrap: 'anywhere' },
  link: { color: 'inherit', textDecoration: 'underline', textDecorationColor: 'var(--color-border-strong)', textUnderlineOffset: '.2em' },
  details: { color: 'var(--color-text-muted)', fontSize: '.8rem', margin: '.15rem 0 0', overflowWrap: 'anywhere' },
  summary: { display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: '.5rem 1rem', margin: '.75rem 0 0' },
  summaryText: { flex: '1 1 18rem', margin: 0, overflowWrap: 'anywhere' },
  note: { flex: '1 1 100%', margin: 0 },
  outside: { fontSize: '1rem', margin: '1.25rem 0 0' }
} satisfies Record<string, CSSProperties>;
const stateLabels = { pending: 'catalog.album_track_state_pending', failed: 'catalog.album_track_state_failed',
  deleting: 'catalog.album_track_state_deleting', unpublished: 'catalog.album_track_state_unpublished',
  unavailable: 'catalog.album_track_state_unavailable' } as const;
/** Joins the known details of a line with a middle dot. */
const details = (parts: Array<string | null | false>) => parts.filter(Boolean).join(' \u00b7 ');
/** An expected row's duration rounded to whole seconds: m:ss, or h:mm:ss from one hour. */
const expectedDuration = (ms: number) => {
  const total = Math.round(ms / 1000), hours = Math.floor(total / 3600), minutes = Math.floor(total % 3600 / 60);
  const seconds = String(total % 60).padStart(2, '0');
  return hours ? `${hours}:${String(minutes).padStart(2, '0')}:${seconds}` : `${minutes}:${seconds}`;
};

/**
 * Read-only member list of an Album page in the Album order. Ordering and editing stay on each MediaTrack's own catalog
 * page, which only a ready MediaTrack has; the editor rereads this list (`refresh`) after its Refresh, a newer Album revision
 * and a refused clear. With an expected tracklist, members are listed on its rows by Disc then Track Number, keeping their
 * Album-order numbers; a row without a member has no file yet, and members at no row's position are listed after the rows.
 * Clear is offered only for a current read, so its confirmation names the rows read after the revision the clear is sent at.
 */
export function CatalogAlbumTracks({ id, refresh, primaryArtistCredit, onClearExpected, clearDisabled = false }: {
  id: string; refresh: number;
  /** Whether the saved Album has a primary Artist Credit, which an append needs; undefined while unknown. */
  primaryArtistCredit?: boolean;
  /** Opens the editor's clear confirmation with what it removes, when known; absent when catalog editing is not permitted. */
  onClearExpected?: (summary: CatalogAlbumExpectedSummary | undefined) => void;
  clearDisabled?: boolean;
}) {
  const t = useAdminText(), access = useAdminAccess(), { t: sharedText, locale } = useLocalization();
  // A key apart from the Album snapshot's, which the editor cancels and resets around its own writes.
  const query = useQuery({
    queryKey: ['admin-imports', access.viewerId, access.epoch, access.generation, 'catalog-album-tracks', id],
    queryFn: ({ signal }) => adminEndpointRequest(`/catalog/album/${id}/tracks`, catalogAlbumTracksSchema.refine(value => value.albumId === id), { signal }),
    retry: false, gcTime: 0
  });
  const { refetch } = query, seen = useRef(refresh);
  // Only a later refresh rereads; the mount read already runs, even when the page was refreshed before this mounted.
  useEffect(() => { if (refresh === seen.current) return; seen.current = refresh; void refetch(); }, [refresh, refetch]);
  const row = (track: CatalogAlbumTrack) => {
    if (track.state === 'missing') return <li key={track.id} style={layout.row}><span style={layout.position}>{track.position}</span>
      <div><span style={layout.title}>{t('catalog.album_track_missing')}</span><p style={layout.details}>{track.id}</p></div></li>;
    const title = track.title.trim() || sharedText('content.title.untitled_track');
    const text = details([track.discNumber ? `${t('field.discNumber')} ${track.discNumber}` : null, track.trackNumber ? `${t('field.trackNumber')} ${track.trackNumber}` : null,
      track.duration, sharedText(track.mediaType === 'video' ? 'common.label.video' : 'common.label.audio')]);
    return <li key={track.id} style={layout.row}><span style={layout.position}>{track.position}</span>
      <div>{track.state === 'ready' ? <Link style={{ ...layout.title, ...layout.link }} to={`/admin/catalog/audioTrack/${track.id}`}>{title}</Link> : <span style={layout.title}>{title}</span>}
        <p style={layout.details}>{text}</p>
        {(track.visibility === 'hidden' || track.state !== 'ready' || track.linkedElsewhere) && <div className={styles.badges}>
          {track.visibility === 'hidden' && <span className={styles.badge}>{t('field.hidden')}</span>}
          {track.state !== 'ready' && <span className={styles.badge}>{t(stateLabels[track.state])}</span>}
          {track.linkedElsewhere && <span className={styles.badge}>{t('catalog.album_track_linked_elsewhere')}</span>}</div>}
      </div></li>;
  };
  /**
   * A row without a listed member is not a track: it has no Album-order number and no catalog page. Past the read bound its
   * member may be unlisted, so it is not called a row without a file.
   */
  const noFileRow = (expected: CatalogAlbumExpectedRow, partial: boolean) => <li key={`expected:${expected.discNumber}:${expected.trackNumber}`} style={layout.row}>
    <span style={layout.position} />
    <div><span style={layout.title}>{expected.title}</span>
      <p style={layout.details}>{details([`${t('field.discNumber')} ${expected.discNumber}`, `${t('field.trackNumber')} ${expected.trackNumber}`,
        expected.durationMs !== null && expectedDuration(expected.durationMs)])}</p>
      {!partial && <div className={styles.badges}><span className={styles.badge}>{t('catalog.album_expected_no_file')}</span></div>}
    </div></li>;
  const data = query.data, expected = data?.expected ?? null;
  const copy = expected ? 'catalog.album_expected_copy' : data?.order === 'legacyAlbumLinks' ? 'catalog.album_tracks_legacy' : 'catalog.album_tracks_copy';
  // Only a settled, successful read may be cleared: a pending or failed reread still shows rows an older revision named.
  const clearBlocked = clearDisabled || query.isFetching || query.isError;
  const expectedList = () => {
    if (!data || !expected) return null;
    // A truncated Album matches rows only to its listed members, so no file count, upload note or summary of them is stated.
    const partial = data.truncated, summary = partial ? undefined : expectedSummary(expected), byId = new Map(data.tracks.map(track => [track.id, track]));
    const outside = new Set(expected.outsideMemberIds), outsideTracks = data.tracks.filter(track => track.state === 'missing' || outside.has(track.id));
    return <>
      <div style={layout.summary}>
        <p style={layout.summaryText}>{summary ? t('catalog.album_expected_summary', expectedSummaryVariables(summary, locale)) : t('catalog.album_expected')}</p>
        {summary && summary.noFile > 0 && primaryArtistCredit === false && <p className={styles.muted} style={layout.note}>{t('catalog.album_expected_upload_only')}</p>}
        {onClearExpected && <button className={styles.button} type="button" disabled={clearBlocked}
          onClick={() => { if (!clearBlocked) onClearExpected(summary); }}>{t('catalog.album_expected_clear')}</button>}
      </div>
      <ol role="list" aria-label={t('catalog.album_expected')} style={layout.list}>
        {expected.rows.map(value => value.memberIds.length ? value.memberIds.map(memberId => row(byId.get(memberId)!)) : noFileRow(value, partial))}
      </ol>
      {outsideTracks.length > 0 && <><h3 id="catalog-album-outside" style={layout.outside}>{t('catalog.album_expected_outside')}</h3>
        <ol role="list" aria-labelledby="catalog-album-outside" style={layout.list}>{outsideTracks.map(row)}</ol></>}
    </>;
  };
  return <section className={styles.panel} aria-labelledby="catalog-album-tracks">
    <header className={styles.sectionHeader}><h2 id="catalog-album-tracks">{t('catalog.album_tracks')}</h2></header>
    <p className={styles.muted}>{t(copy)}</p>
    {query.isPending && <p role="status">{t('common.loading')}</p>}
    {query.isError && <div className={styles.error} role="alert"><p>{t('catalog.album_tracks_error')}</p>
      <button className={styles.button} type="button" disabled={query.isFetching} onClick={() => void refetch()}>{t('common.retry')}</button></div>}
    {/* An explicit role keeps the list and its item count for VoiceOver, which drops them from unmarked lists. */}
    {data && (expected ? expectedList() : data.tracks.length ? <ol role="list" style={layout.list}>{data.tracks.map(row)}</ol> : <p>{t('catalog.album_tracks_empty')}</p>)}
    {data?.skipped ? <p className={styles.muted}>{t('catalog.album_tracks_skipped', { count: data.skipped })}</p> : null}
    {data?.truncated && <p className={styles.muted}>{t('catalog.album_tracks_truncated', { count: data.tracks.length })}</p>}
  </section>;
}
